mapper.insert:
INSERT INTO MES_TC_SCHEDULE_RESULT () SELECT * FROM (
SELECT #{item.scheduleDate} AS SCHEDULE_DATE, #{item.batchNo} AS BATCH_NO, #{item.orderNo} AS ORDER_NO, #{item.sidewallCode} AS SIDEWALL_CODE, #{item.machineCode} AS MACHINE_CODE, #{item.glueCode} AS GLUE_CODE, #{item.baseGlueCode} AS BASE_GLUE_CODE, #{item.wholeGlueCode} AS WHOLE_GLUE_CODE, #{item.glueSeq} AS GLUE_SEQ, #{item.mouthPlateCode} AS MOUTH_PLATE_CODE, #{item.constructionVersion} AS CONSTRUCTION_VERSION, #{item.sidewallCraft} AS SIDEWALL_CRAFT, #{item.midPlanQty} AS MID_PLAN_QTY, #{item.midProduceOrder} AS MID_PRODUCE_ORDER, #{item.midAnalysis} AS MID_ANALYSIS, #{item.nightPlanQty} AS NIGHT_PLAN_QTY, #{item.nightProduceOrder} AS NIGHT_PRODUCE_ORDER, #{item.nightAnalysis} AS NIGHT_ANALYSIS, #{item.dayPlanQty} AS DAY_PLAN_QTY, #{item.dayProduceOrder} AS DAY_PRODUCE_ORDER, #{item.dayAnalysis} AS DAY_ANALYSIS, #{item.tailFlag} AS TAIL_FLAG, '1' AS IS_RELEASE, #{item.dataVersion} AS DATA_VERSION, #{item.taskVersion} AS TASK_VERSION, #{item.idempotencyKey} AS IDEMPOTENCY_KEY, #{item.companyCode} AS COMPANY_CODE, #{item.factoryCode} AS FACTORY_CODE
) AS source_data WHERE NOT EXISTS ( SELECT 1 FROM MES_TC_SCHEDULE_RESULT target_data WHERE target_data.SCHEDULE_DATE = source_data.SCHEDULE_DATE AND target_data.MACHINE_CODE = source_data.MACHINE_CODE AND target_data.SIDEWALL_CODE = source_data.SIDEWALL_CODE AND target_data.DATA_VERSION = source_data.DATA_VERSION )

mapper.select:
SELECT SCHEDULE_DATE, MACHINE_CODE, SIDEWALL_CODE, DATA_VERSION
FROM MES_TC_SCHEDULE_RESULT
WHERE

    (SCHEDULE_DATE = #{item.scheduleDate}
     AND MACHINE_CODE = #{item.machineCode}
     AND SIDEWALL_CODE = #{item.sidewallCode}
     AND DATA_VERSION = #{item.dataVersion})

mapper.delete:
DELETE FROM MES_TC_SCHEDULE_RESULT
WHERE SCHEDULE_DATE = #{scheduleDate}
  AND DATA_VERSION = #{dataVersion}
